func HowManyTimes(str string, substring string) int {
	count := 0
	if len(substring) == 0 {
		return 0
	}

	for len(str) >= len(substring) {
		if str[:len(substring)] == substring {
			count++
		}
		str = str[1:]
	}

	return count
}

