func HowManyTimes(str string, substring string) int {
    if substring == "" {
        return 0
    }

    count := 0
    subLen := len(substring)
    strLen := len(str)

    subHash := 0
    strHash := 0
    base := 26
    prime := 31
    power := 1

    for i := 0; i < subLen; i++ {
        subHash = subHash*base + int(substring[i])
        strHash = strHash*base + int(str[i])
        if i != 0 {
            power = power * base
        }
    }

    if subHash == strHash {
        count++
    }

    for i := subLen; i < strLen; i++ {
        strHash = (strHash - int(str[i-subLen])*power) * base + int(str[i])
        if strHash == subHash {
            count++
        }
    }

    return count
}

