			next := prev + current
			prev = current
			current = next
		}
		return current
	}

    isPrime := func(num int) bool {
		if num <= 1 {
			return false
		}
		for i := 2; i < num; i++ {
			if num%i == 0 {
				return false
			}
		}
		return true
	}

	count := 0
	num := 2
	for {
		fibNum := fib(num)
		if isPrime(fibNum) {
			count++
			if count == n {
				return fibNum
			}
		}
		num++
	}
}

