func TriplesSumToZero(l []int) bool {
    if len(l) < 3 {
        return false
    }

    sort.Ints(l)

    for i := 0; i < len(l)-2; i++ {
        left := i + 1
        right := len(l) - 1

        for left < right {
            sum := l[i] + l[left] + l[right]
            if sum == 0 {
                return true
            } else if sum < 0 {
                left++
            } else {
                right--
            }
        }
    }

    return false
}

