func ChangeBase(x int, base int) string {
    if x == 0 {
        return "0"
    }

    var result string
    digits := "0123456789"
    for x > 0 {
        remainder := x % base
        result = string(digits[remainder]) + result
        x /= base
    }

    return result
}

