import (
	"sort"
)

func Monotonic(l []int) bool {
    sorted := make([]int, len(l))
    copy(sorted, l)
    sort.Ints(sorted)

    return reflect.DeepEqual(l, sorted) || reflect.DeepEqual(l, reverse(sorted))
}

func reverse(a []int) []int {
    for i := 0; i < len(a)/2; i++ {
        j := len(a) - i - 1
        a[i], a[j] = a[j], a[i]
    }
    return a
}

