func CorrectBracketing(brackets string) bool {
    bracketMap := map[rune]rune{'(': ')', '[': ']', '{': '}'}
    stack := make([]rune, 0)

    for _, b := range brackets {
        if b == '(' || b == '[' || b == '{' {
            stack = append(stack, b)
        } else if b == ')' || b == ']' || b == '}' {
            if len(stack) == 0 || bracketMap[stack[len(stack)-1]] != b {
                return false
            }
            stack = stack[:len(stack)-1]
        }
    }

    return len(stack) == 0
}

