func NumericalLetterGrade(grades []float64) []string {
    gradeHash := map[float64]string{
        4.0: "A+",
        3.7: "A",
        3.3: "A-",
        3.0: "B+",
        2.7: "B",
        2.3: "B-",
        2.0: "C+",
        1.7: "C",
        1.3: "C-",
        1.0: "D+",
        0.7: "D",
        0.0: "D-",
    }

    var result []string
    for _, gpa := range grades {
        var grade string
        for key, value := range gradeHash {
            if gpa >= key {
                grade = value
                break
            }
        }
        result = append(result, grade)
    }
    return result
}

