    result := make([]int, n)

    cache := make(map[int]int)
    cache[0] = 1
    cache[1] = 1

    for i := 1; i <= n; i++ {
        if i%2 == 0 {
            result[i-1] = cacheFactorial(i, cache)
        } else {
            result[i-1] = cacheSum(i, cache)
        }
