func MaxFill(grid [][]int, capacity int) int {
	rows := len(grid)
	cols := len(grid[0])

	buckets := 0

	for col := 0; col < cols; col++ {
		for row := 0; row < rows; row++ {
			if grid[row][col] == 1 {
				buckets += int(math.Ceil(float64(grid[row][col]) / float64(capacity)))
			}
		}
	}

	return buckets
}

