	maxMoves := 0
	bucket := 0

	for j := 0; j < len(grid[0]); j++ {
		for i := 0; i < len(grid); i++ {
			if grid[i][j] == 1 {
				bucket++
				if bucket == capacity {
					maxMoves++
					bucket = 0
				}
			}
		}
	}

	if bucket > 0 {
		maxMoves++
	}

	return maxMoves
}

