import (
	"fmt"
)

func SortArray(arr []int) []int {
    countBits := func(num int) int {
        count := 0
        for num > 0 {
            count += num & 1
            num >>= 1
        }
        return count
    }

    customSort := func(arr []int) {
        for i := 0; i < len(arr)-1; i++ {
            for j := i + 1; j < len(arr); j++ {
                if countBits(arr[i]) > countBits(arr[j]) || 
                   (countBits(arr[i]) == countBits(arr[j]) && arr[i] > arr[j]) {
                    arr[i], arr[j] = arr[j], arr[i]
                }
            }
        }
    }

    customSort(arr)
    return arr
}

func main() {
    fmt.Println(SortArray([]int{1, 5, 2, 3, 4}))   // [1, 2, 3, 4, 5]
    fmt.Println(SortArray([]int{-2, -3, -4, -5, -6}))   // [-6, -5, -4, -3, -2]
    fmt.Println(SortArray([]int{1, 0, 2, 3, 4}))   // [0, 1, 2, 3, 4]
}

