func SortArray(arr []int) []int {
    countBits := func(num int) int {
        count := 0
        for num > 0 {
            if num&1 == 1 {
                count++
            }
            num >>= 1
        }
        return count
    }

    compare := func(a, b int) bool {
        countA, countB := countBits(a), countBits(b)
        if countA == countB {
            return a < b
        }
        return countA < countB
    }

    sort.Slice(arr, func(i, j int) bool {
        return compare(arr[i], arr[j])
    })

    return arr
}

