	oddCount := 0

	for _, char := range txt {
		if char >= 'a' && char <= 'z' {
			charMap[char] = !charMap[char]
		}
	}

	for _, isOdd := range charMap {
		if isOdd {
			oddCount++
		}
	}

	if oddCount == 0 {
		return strings.Split(txt, ",")
	} else {
		return oddCount
	}
