func SplitWords(txt string) interface{} {
    words := make([]string, 0)
    currentWord := ""
    commaSplit := false

    for _, char := range txt {
        if char == ' ' {
            if currentWord != "" {
                words = append(words, currentWord)
                currentWord = ""
            }
        } else if char == ',' {
            commaSplit = true
        } else {
            currentWord += string(char)
        }
    }

    if currentWord != "" {
        words = append(words, currentWord)
    }

    if len(words) > 0 {
        return words
    }

    if commaSplit {
        return []string{txt}
    }

    lowercaseOddCount := 0
    for _, char := range txt {
        if char >= 'a' && char <= 'z' && (int(char-'a'))%2 == 1 {
            lowercaseOddCount++
        }
    }

    return lowercaseOddCount
}

