func IsSorted(lst []int) bool {
    if len(lst) <= 1 {
        return true
    }

    for i := 1; i < len(lst); i++ {
        if lst[i] < lst[i-1] {
            return false
        }

        for j := i + 1; j < len(lst); j++ {
            if lst[i] == lst[j] {
                return false
            }
        }
    }

    return true
}

