func IsSorted(lst []int) bool {
    sorted := true
    duplicates := make(map[int]int)

    for i, num := range lst {
        if i > 0 && num < lst[i-1] {
            sorted = false
        }
        duplicates[num]++
        if duplicates[num] > 1 {
            return false
        }
    }

    return sorted
}

