	"sort"
)

func IsSorted(lst []int) bool {
    sortedList := make([]int, len(lst))
    copy(sortedList, lst)
    sort.Ints(sortedList)

    if len(lst) != len(sortedList) {
        return false
    }

    for i := 0; i < len(lst); i++ {
        if lst[i] != sortedList[i] {
            return false
        }
