	planets := map[string]int{
		"Mercury": 1,
		"Venus":   2,
		"Earth":   3,
		"Mars":    4,
		"Jupiter": 5,
		"Saturn":  6,
		"Uranus":  7,
		"Neptune": 8,
	}

	if _, ok := planets[planet1]; !ok || _, ok := planets[planet2]; !ok {
		return []string{}
	}

	var result []string
	start, end := planets[planet1], planets[planet2]
	if start > end {
		start, end = end, start
	}

	for k, v := range planets {
		if v > start && v < end {
			result = append(result, k)
		}
	}

	return result
}

data.canonical_solution:
// There are eight planets in our solar system: the closerst to the Sun
// is Mercury, the next one is Venus, then Earth, Mars, Jupiter, Saturn,
// Uranus, Neptune.
// Write a function that takes two planet names as strings planet1 and planet2.
// The function should return a tuple containing all planets whose orbits are
// located between the orbit of planet1 and the orbit of planet2, sorted by
// the proximity to the sun.
// The function should return an empty tuple if planet1 or planet2
// are not correct planet names.
// Examples
// Bf("Jupiter", "Neptune") ==> ("Saturn", "Uranus")
// Bf("Earth", "Mercury") ==> ("Venus")
// Bf("Mercury", "Uranus") ==> ("Venus", "Earth", "Mars", "Jupiter", "Saturn")
func Bf(planet1, planet2 string) []string {
    planet_names := []string{"Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"}
    pos1 := -1
    pos2 := -1
    for i, x := range planet_names {
        if planet1 == x {
            pos1 = i
        }
        if planet2 == x {
            pos2 = i
        }
    }
    if pos1 == -1 || pos2 == -1 || pos1 == pos2 {
        return []string{}
    }
    if pos1 < pos2 {
        return planet_names[pos1 + 1: pos2]
    }
    return planet_names[pos2 + 1 : pos1]
}

