import (
	"sort"
)

func SortedListSum(lst []string) []string {
    i := 0
    for j := 0; j < len(lst); j++ {
        if len(lst[j])%2 == 0 {
            lst[i], lst[j] = lst[j], lst[i]
            i++
        }
    }
    lst = lst[:i]

    sort.Slice(lst, func(i, j int) bool {
        if len(lst[i]) == len(lst[j]) {
            return lst[i] < lst[j]
        }
        return len(lst[i]) < len(lst[j])
    })

    return lst
}

