func DoAlgebra(operator []string, operand []int) int {
	result := operand[0]

	for i := 0; i < len(operator); i++ {
		if operator[i] == "+" {
			result += operand[i+1]
		} else if operator[i] == "-" {
			result -= operand[i+1]
		} else if operator[i] == "*" {
			result *= operand[i+1]
		} else if operator[i] == "//" {
			result /= operand[i+1]
		} else if operator[i] == "**" {
			result = int(math.Pow(float64(result), float64(operand[i+1])))
		}
	}

	return result
}

